def countCoveringSubstrings(s, p):
    need = [0] * 26
    for ch in p:
        need[ord(ch) - 97] += 1
    have = [0] * 26
    missing = len(p)
    left = 0
    ans = 0
    for ch in s:
        c = ord(ch) - 97
        if have[c] < need[c]:
            missing -= 1
        have[c] += 1
        if missing == 0:
            while have[ord(s[left]) - 97] > need[ord(s[left]) - 97]:
                have[ord(s[left]) - 97] -= 1
                left += 1
            ans += left + 1
    return ans
